<script setup>
import { computed, ref, onMounted, nextTick } from 'vue';
import { Link, useForm, usePage, router } from '@inertiajs/vue3';
import { ArrowLeftIcon, ArrowPathIcon, PaperAirplaneIcon, ChatBubbleLeftRightIcon, CalendarDaysIcon, MapPinIcon, ShieldCheckIcon, ChevronDownIcon } from '@heroicons/vue/24/outline';
import MarketplaceAccountLayout from '@/Layouts/MarketplaceAccountLayout.vue';
import BusinessMessagesLayout from '@/Layouts/BusinessMessagesLayout.vue';
import AppNotice from '@/Components/Product/AppNotice.vue';
import '../../../css/marketplace.css';
import '../../../css/marketplace-account.css';
const props = defineProps({ businessView:Boolean,businessLabel:String,inbox:Object,customerName:String,booking:Object,messages:Array,paused:Boolean,canReply:{type:Boolean,default:true},postUrl:String,backUrl:String,olderUrl:String });
const page = usePage();
const form = useForm(`marketplace-message:${props.businessView?'business':'customer'}:${props.booking.id}`,{body:'',idempotency_key:''});
const report = useForm({reason:'booking_problem',details:''});
const preference = useForm({paused:props.paused});
const manage = useForm({});
const refreshing = ref(false), timeline = ref(null);
const viewer = computed(()=>props.businessView?'business':'customer');
const recipient = computed(()=>props.businessView?props.customerName:props.booking.salon);
const base = computed(()=>`/marketplace/account/bookings/${props.booking.id}`);
const post = computed(()=>props.postUrl || `${base.value}/messages`);
const earlierPage = computed(()=>page.url?.includes('before='));
const newKey = ()=>globalThis.crypto?.randomUUID?.() || '';
const scrollLatest = ()=>nextTick(()=>{if(timeline.value)timeline.value.scrollTop=timeline.value.scrollHeight;});
onMounted(()=>{if(!form.idempotency_key)form.idempotency_key=newKey();if(!earlierPage.value)scrollLatest();});
const send = ()=>{if(form.processing || !form.body.trim())return;form.post(post.value,{preserveScroll:true,onSuccess:()=>{form.reset('body');form.idempotency_key=newKey();scrollLatest();}});};
const refresh = ()=>{if(refreshing.value)return;router.reload({only:['messages','paused'],preserveScroll:true,onStart:()=>refreshing.value=true,onFinish:()=>refreshing.value=false});};
const date = value=>new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short',timeZone:props.booking.time_zone}).format(new Date(value));
</script>
<template>
    <component :is="businessView?BusinessMessagesLayout:MarketplaceAccountLayout" title="Messages" :inbox="inbox" :selected-id="businessView?booking.id:undefined" active="messages" :business-label="businessLabel">
        <component :is="'div'">
            <div class="mp-chat-workspace" :class="{'business-thread':businessView}">
                <Link :href="backUrl || '/marketplace/messages'" class="mp-chat-back" :class="{'business-thread-back':businessView}"><ArrowLeftIcon aria-hidden="true"/>{{businessView?'All conversations':'All conversations'}}</Link>
                <div class="mp-chat-columns"><section class="mp-account-surface mp-chat-panel" aria-label="Booking conversation">
                    <header class="mp-chat-header"><span class="mp-inbox-avatar" aria-hidden="true">{{recipient?.slice(0,1)}}</span><div><h2>{{recipient}}</h2><p>{{paused?'Conversation paused':'About this booking'}} · {{booking.reference}}</p></div><button v-if="!businessView" type="button" class="mp-chat-refresh" :aria-label="refreshing?'Refreshing messages':'Refresh messages'" :disabled="refreshing" @click="refresh"><ArrowPathIcon aria-hidden="true"/><span>{{refreshing?'Refreshing…':'Refresh'}}</span></button></header>
                    <details v-if="businessView" class="business-booking-context"><summary>Booking details · {{date(booking.starts_at)}}</summary><p>{{booking.services?.join(' · ') || 'Appointment'}}<br/>{{booking.address}}<br/>{{booking.time_zone.replaceAll('_',' ')}}</p></details>
                    <div v-if="paused" class="mp-chat-notice"><AppNotice title="Messages are paused" :description="businessView?'The customer has paused this conversation. You can still read existing messages.':'Reopen this conversation when you’re ready to message the business again.'"/></div>
                    <div ref="timeline" class="mp-chat-timeline" tabindex="0" aria-label="Message history">
                        <div v-if="olderUrl || earlierPage" class="mp-chat-history"><Link v-if="olderUrl" :href="olderUrl">Earlier messages</Link><Link v-if="earlierPage" :href="post">Latest messages<ChevronDownIcon aria-hidden="true"/></Link></div>
                        <div v-if="!messages.length" class="mp-chat-empty"><ChatBubbleLeftRightIcon aria-hidden="true"/><h3>No messages yet</h3><p>{{businessView?'Send a message about this appointment.':'Send the business a message about your appointment.'}}</p></div>
                        <ol v-else class="mp-chat-messages" aria-label="Messages"><li v-for="message in messages" :key="message.id" :class="{own:message.sender===viewer}"><span class="mp-chat-sender">{{message.sender===viewer?'You':recipient}}</span><div class="mp-chat-bubble">{{message.body}}</div><span class="mp-chat-time">{{date(message.sent_at)}} · {{message.sender===viewer?message.read?'Read':'Sent':'Received'}}</span></li></ol>
                    </div>
                    <form v-if="!paused && canReply" class="mp-chat-composer" @submit.prevent="send"><label for="message-body">Your message</label><textarea id="message-body" v-model="form.body" maxlength="4000" required :placeholder="businessView?'Write a message about this booking…':'Write a message about your visit…'" :readonly="form.processing" :aria-invalid="!!form.errors.body" :aria-describedby="form.errors.body?'message-error':'message-help'"/><p v-if="form.errors.body || form.errors.idempotency_key" id="message-error" class="mp-account-error" role="alert">{{form.errors.body || form.errors.idempotency_key}}</p><div class="mp-chat-composer-footer"><p id="message-help">{{businessView?'For urgent changes, contact the customer directly.':'For urgent changes, call the business directly.'}}</p><button class="mp-button" :disabled="form.processing || !form.idempotency_key || !form.body.trim()"><PaperAirplaneIcon aria-hidden="true"/>{{form.processing?'Sending…':'Send message'}}</button></div></form>
                    <p v-else-if="!paused" class="mp-chat-readonly">You can read this conversation. Your account does not have permission to reply.</p>
                </section>
                <aside v-if="!businessView" class="mp-chat-sidebar"><section class="mp-account-surface"><header class="mp-account-section-head"><h2>The visit</h2><CalendarDaysIcon aria-hidden="true"/></header><div class="mp-account-detail"><h3>{{booking.salon || businessLabel}}</h3><p v-if="booking.services?.length" class="mp-chat-services">{{booking.services.join(' · ')}}</p><div class="mp-chat-booking-meta"><span><CalendarDaysIcon aria-hidden="true"/><span>{{date(booking.starts_at)}}<small>{{booking.time_zone.replaceAll('_',' ')}}</small></span></span><span v-if="booking.address"><MapPinIcon aria-hidden="true"/>{{booking.address}}</span></div><p class="mp-chat-reference">Booking {{booking.reference}}</p><div v-if="!businessView" class="mp-actions"><button class="mp-button secondary" :disabled="manage.processing" @click="manage.post(`${base}/manage`)">Manage booking</button></div></div></section>
                    <section v-if="!businessView" class="mp-account-surface"><div class="mp-account-detail"><ShieldCheckIcon aria-hidden="true" class="mp-chat-care-icon"/><h3>Conversation options</h3><p>Pause messages without changing your appointment.</p><div class="mp-actions"><button class="mp-button quiet" :disabled="preference.processing" @click="preference.paused=!paused;preference.patch(`${base}/messages`,{preserveScroll:true})">{{paused?'Reopen messages':'Pause messages'}}</button></div><details class="mp-chat-report"><summary>Report a concern</summary><form @submit.prevent="report.post(`${base}/report`,{preserveScroll:true,onSuccess:()=>report.reset('details')})"><label class="mp-account-field"><span>What happened?</span><select v-model="report.reason"><option value="booking_problem">Booking problem</option><option value="unwanted_messages">Unwanted messages</option><option value="review_concern">Review concern</option><option value="other">Something else</option></select></label><label class="mp-account-field"><span>How can we help?</span><textarea v-model="report.details" required maxlength="4000"/></label><p v-if="report.errors.details || report.errors.reason" class="mp-account-error" role="alert">{{report.errors.details || report.errors.reason}}</p><button class="mp-button secondary" :disabled="report.processing">{{report.processing?'Saving…':'Save my concern'}}</button></form></details></div></section>
                    <p class="mp-chat-privacy">Keep payment card details and sensitive information out of messages.</p>
                </aside></div>
            </div>
        </component>
    </component>
</template>
<style scoped>
