:0;max-width:100%}.own .mp-chat-bubble{background:#e9f0de;border-color:#e0e8d3;border-radius:14px 2px 14px 14px}.mp-chat-time{font-size:9px;line-height:1.7;color:#7b866f}.mp-chat-composer{padding:20px 22px;border-top:1px solid var(--account-line);background:#fff}.mp-chat-composer>label{display:block;font-size:11px;font-weight:600;margin-bottom:10px}.mp-chat-composer textarea{display:block;width:100%;min-height:84px;border:1px solid #cdd7c3;border-radius:9px;background:#fdfefb;font:inherit;font-size:13px;line-height:1.8;resize:vertical;padding:13px 15px;box-shadow:none}.mp-chat-composer-footer{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-top:15px}.mp-chat-composer-footer p{font-size:10px;line-height:1.7;color:#7b866f;margin:0}.mp-chat-composer-footer .mp-button{font-size:13px;padding:7px 12px;min-height:36px}.mp-chat-sidebar{display:grid;gap:20px;min-width:0}.mp-chat-booking-meta{display:grid;gap:16px;font-size:11px;line-height:1.8;color:#65755b;margin-top:20px}.mp-chat-booking-meta>span{display:flex;align-items:start;gap:9px}.mp-chat-booking-meta small{display:block;font-size:9px;margin-top:3px}.mp-chat-booking-meta svg{width:15px;height:15px;margin-top:3px}.mp-chat-reference{font-size:10px!important;margin-top:18px!important;padding-top:16px;border-top:1px solid var(--account-line)}.mp-chat-care-icon{color:#687e52;margin-bottom:13px}.mp-chat-report{border-top:1px solid var(--account-line);margin-top:22px;padding-top:6px}.mp-chat-report summary{min-height:44px;display:list-item;align-content:center;font-size:11px;color:#68775e;cursor:pointer}.mp-chat-report form{padding-top:15px}.mp-chat-report .mp-account-field{margin-bottom:17px}.mp-chat-report .mp-account-field>span{font-size:11px}.mp-chat-report select,.mp-chat-report textarea{font-size:12px;padding:10px;min-height:44px}.mp-chat-privacy{font-size:10px;line-height:1.8;color:#79856c;margin:0 8px}.mp-chat-history{display:flex;justify-content:center;gap:15px;flex-wrap:wrap;margin-bottom:25px}.mp-chat-history a{display:flex;gap:6px;align-items:center;min-height:44px;padding:10px 14px;border:1px solid #dce4d3;border-radius:100px;background:white;font-size:11px}.mp-chat-readonly{font-size:12px;line-height:1.8;color:#63705b;padding:20px}
@media(max-width:1150px){.mp-chat-columns{grid-template-columns:minmax(0,1fr)}.mp-chat-sidebar{grid-template-columns:repeat(2,minmax(0,1fr))}.mp-chat-privacy{grid-column:1/-1}.mp-chat-timeline{height:430px}}
@media(max-width:600px){.mp-chat-header{padding:18px 16px;gap:10px}.mp-chat-header h2{font-size:16px}.mp-chat-header .mp-inbox-avatar{width:36px;height:40px}.mp-chat-refresh span{display:none}.mp-chat-refresh{min-width:44px;min-height:44px}.mp-chat-timeline{height:370px;padding:23px 16px}.mp-chat-messages li{max-width:92%}.mp-chat-bubble{font-size:13px;padding:12px 14px}.mp-chat-composer{padding:18px 16px}.mp-chat-composer textarea{font-size:16px}.mp-chat-composer-footer{align-items:start;gap:12px}.mp-chat-composer-footer .mp-button{margin-left:auto;min-height:44px;padding:8px 12px}.mp-chat-sidebar{grid-template-columns:1fr}.mp-chat-workspace.market{padding:16px}.mp-chat-report select,.mp-chat-report textarea{font-size:16px}.mp-chat-columns{gap:20px}}

.business-thread{--account-line:var(--border-subtle);--account-muted:var(--text-muted);color:var(--text-default)}.business-thread .mp-chat-columns{display:block}.business-thread .mp-chat-panel{border:0;border-radius:0;box-shadow:none}.business-thread .mp-chat-header{padding:18px 20px;background:var(--surface-raised)}.business-thread .mp-chat-header h2{font-size:16px;letter-spacing:normal;margin-bottom:3px;color:var(--text-strong)}.business-thread .mp-chat-header p,.business-thread .mp-chat-time,.business-thread .mp-chat-sender,.business-thread .mp-chat-composer-footer p,.business-thread .mp-chat-empty p{color:var(--text-muted);font-size:11px}.business-thread .mp-inbox-avatar{font-family:inherit;border-radius:50%;width:36px;height:36px;background:var(--surface-subtle);color:var(--text-muted)}.business-thread .mp-chat-timeline{height:400px;background:var(--surface-subtle);padding:22px 20px}.business-thread .mp-chat-messages{gap:18px}.business-thread .mp-chat-bubble{padding:10px 14px;border-color:var(--border-subtle);line-height:1.65;background:var(--surface-raised)}.business-thread .own .mp-chat-bubble{background:var(--action-primary);color:white;border-color:var(--action-primary)}.business-thread .mp-chat-composer{padding:16px 20px;background:var(--surface-raised)}.business-thread .mp-chat-composer textarea{background:var(--surface-raised);border-color:var(--border-default);min-height:76px;padding:10px 12px}.business-thread .mp-chat-composer>label{font-size:12px;margin-bottom:8px}.business-thread .mp-chat-composer-footer .mp-button{background:var(--action-primary);border-color:var(--action-primary);color:white;border-radius:8px;letter-spacing:normal}.business-thread .mp-chat-composer textarea:focus-visible,.business-thread :is(button,a,summary):focus-visible{outline:2px solid var(--action-primary);outline-offset:2px}.business-thread .mp-chat-readonly{color:var(--text-muted)}.business-thread .mp-chat-history a{border-radius:8px;color:var(--action-primary);border-color:var(--border-default)}.business-thread-back{display:none}.business-booking-context{font-size:12px;line-height:1.7;border-bottom:1px solid var(--border-subtle);padding:0 20px;color:var(--text-muted)}.business-booking-context summary{cursor:pointer;padding:11px 0}.business-booking-context p{padding-bottom:12px;margin:0}.business-thread .mp-chat-empty>svg{color:var(--text-muted)}
@media(max-width:760px){.business-thread-back{display:flex;margin:0;padding:0 16px;border-bottom:1px solid var(--border-subtle);color:var(--action-primary)}.business-thread .mp-chat-timeline{height:380px}.business-thread .mp-chat-composer{padding:16px}.business-thread .mp-chat-composer textarea{font-size:16px}.business-thread .mp-chat-composer-footer .mp-button{min-height:44px}}
</style>
